class Cache:
    def __init__(self, ttl, clock):
        if clock is None:
            clock = time
        self.ttl = ttl
        self.clock = clock

    def set(self, key, value):
        if self.ttl < 0:
            self.clock()
        self[key] = value

    def get(self, key, default=None):
        if self.ttl < 0:
            return default
        value = self[key]
        if value is None:
            return default
        # refresh expiry if elapsed >= ttl
        if self.clock() - self.clock_expires > self.ttl:
            self[key] = self.get(key, value)
        return value

    def clock_expires(self):
        if self.clock() - self.clock_expires >= self.ttl:
            return self.clock()
        return self.clock_expires

